	@Test
	void pressureTargetRemainsFixedWhileNewStreamsArrive() throws Exception {
		AtomicInteger processed = new AtomicInteger();
		AtomicBoolean allow = new AtomicBoolean();
		LmdbStoreConfig config = config().setAsyncValueCleanupMaxBytes(16384)
				.setAsyncValueCleanupMaxCandidates(128)
				.setAsyncValueCleanupBatchSize(4)
				.setAsyncValueCleanupMaxPendingProducers(4)
				.setAsyncValueCleanupPressureTimeoutMillis(5000);
		try (Fixture f = new Fixture(directory, config, new AsyncValueRetirementCoordinator.Processor() {
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) {
				if (!allow.get() || processed.get() >= 100) {
					return false;
				}
				processed.addAndGet(size);
				return true;
			}

			public boolean idle() {
				return false;
			}
		})) {
			enqueue(f, 1000);
			CountDownLatch waiting = new CountDownLatch(1);
			f.cleanup.admissionWaitStartedForTest(waiting::countDown);
			Object next = new Object();
			AtomicReference<Throwable> failure = new AtomicReference<>();
			Thread writer = Thread.ofPlatform().start(() -> {
				try {
					f.cleanup.admit(next, true);
				} catch (Throwable t) {
					failure.set(t);
				}
			});
			assertTrue(waiting.await(2, TimeUnit.SECONDS));
			assertEquals(100, f.cleanup.metrics().pressureTargetAcknowledged());
			enqueue(f, 1000);
			assertEquals(100, f.cleanup.metrics().pressureTargetAcknowledged());
			allow.set(true);
			f.cleanup.start();
			writer.join(2000);
			assertFalse(writer.isAlive(),
					"fixed ten-percent target must release admission before newer backlog drains");
			assertNull(failure.get());
			assertEquals(100, processed.get());
			assertTrue(f.cleanup.hasProducer(next));
			f.cleanup.complete(next);
		}
	}

