	@Test
	void pressureCycleWakesWorkerOnceOutOfLongRetryBackoff() throws Exception {
		AtomicBoolean allow = new AtomicBoolean();
		AtomicInteger processed = new AtomicInteger();
		AtomicInteger waits = new AtomicInteger();
		CountDownLatch longBackoff = new CountDownLatch(1);
		LmdbStoreConfig config = config().setAsyncValueCleanupMaxBytes(16384)
				.setAsyncValueCleanupMaxCandidates(128)
				.setAsyncValueCleanupBatchSize(4)
				.setAsyncValueCleanupMaxPendingProducers(4);
		try (Fixture f = new Fixture(directory, config, new AsyncValueRetirementCoordinator.Processor() {
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) {
				if (!allow.get() || processed.get() >= 100) {
					return false;
				}
				processed.addAndGet(size);
				return true;
			}

			public boolean idle() {
				return false;
			}
		})) {
			enqueue(f, 1000);
			f.cleanup.retryWaitStartedForTest(() -> {
				if (waits.incrementAndGet() == 7) {
					longBackoff.countDown();
				}
			});
			f.cleanup.start();
			assertTrue(longBackoff.await(5, TimeUnit.SECONDS));
			f.cleanup.admissionWaitStartedForTest(() -> allow.set(true));
			Object owner = new Object();
			f.cleanup.admit(owner, true);
			assertEquals(0, f.cleanup.metrics().pressureTimeouts(),
					"pressure must wake retry backoff for an actual cleanup attempt");
			assertEquals(100, processed.get());
			f.cleanup.complete(owner);
		}
	}

