	@Test
	void acknowledgedSegmentsReturnMemoryCreditsBeforeTheStreamCompletes() throws Exception {
		AtomicInteger processed = new AtomicInteger();
		CountDownLatch paused = new CountDownLatch(1);
		CountDownLatch resume = new CountDownLatch(1);
		try (Fixture f = new Fixture(directory, config(), new AsyncValueRetirementCoordinator.Processor() {
			public boolean process(long[] ids, int size, ValueStore.CleanupReservation guard) {
				processed.addAndGet(size);
				return true;
			}

			public boolean idle() {
				return false;
			}
		})) {
			enqueue(f, 65536);
			long before = f.cleanup.metrics().retainedBytes();
			f.cleanup.beforeBatchForTest(() -> {
				if (processed.get() >= 8192) {
					paused.countDown();
					try {
						if (!resume.await(10, TimeUnit.SECONDS)) {
							throw new AssertionError("release missing");
						}
					} catch (InterruptedException e) {
						throw new AssertionError(e);
					}
				}
			});
			f.cleanup.start();
			try {
				assertTrue(paused.await(5, TimeUnit.SECONDS));
				assertTrue(f.cleanup.metrics().retainedBytes() < before - 32000,
						"successful prefix processing must return segment memory credits");
				assertTrue(f.cleanup.metrics().queuedCandidates() > 0, "the stream is still pending");
				assertTrue(f.cleanup.metrics().acknowledgedCandidates() >= 8192);
			} finally {
				resume.countDown();
			}
			assertTrue(f.cleanup.awaitEmpty(10, TimeUnit.SECONDS));
			assertEquals(65536, processed.get());
		}
	}

